/**
 * Метка сборки. Значение подставляет Vite (`define` в app/vite.config.ts):
 * на Cloudflare — короткий хеш коммита, локально — время сборки.
 *
 * Нужна ровно для одного: адрес служебного работника `sw.js?v=<метка>` меняется
 * с каждой выкладкой, и браузер обязан перекачать сценарий, а не жить со старым.
 */
declare const __BUILD__: string
